// A separate 100-stage adventure for every game. Only a win unlocks the next stage.
function unlockedStage(mode=selectedGame().id){return Math.min(100,1+Math.max(0,Math.floor(Number(profile.gameProgress?.[mode]?.clears)||0)))}
missionStage=function(mode=selectedGame().id){return Math.max(1,Math.min(unlockedStage(mode),Math.floor(Number(profile.gameProgress?.[mode]?.selectedStage)||unlockedStage(mode))))};
missionThreat=function(mode=selectedGame().id){return Math.min(10,1+Math.floor((playerLevel()-1)/9)+Math.floor((missionStage(mode)-1)/12)+(selectedMode().id==='expert'?2:selectedMode().id==='challenger'?1:0))};
function stageProgressPanel(){const mode=selectedGame().id,clears=Math.min(100,profile.gameProgress?.[mode]?.clears||0),stage=missionStage(mode);return `<section class="stage-progress-panel"><div><small>YOUR 100-STAGE ADVENTURE</small><h2>${selectedGame().name} · Stage ${stage} / 100</h2><p>${clears===100?'All 100 stages cleared! Replay any stage.':`${clears} stages cleared. Win stage ${unlockedStage(mode)} to unlock the next. Unsuccessful attempts stay on the same stage.`}</p><div class="track"><span style="width:${clears}%"></span></div></div><button class="secondary" data-stage-menu="${mode}">View all 100 stages →</button></section>`}
const centuryHome=home;home=function(){return centuryHome().replace('<section class="field-shortcuts">',stageProgressPanel()+'<section class="field-shortcuts">')};
function openStageMenu(mode){const info=GAME_MODES.find(m=>m.id===mode);if(!info)return;const unlocked=unlockedStage(mode),selected=missionStage(mode),clears=Math.min(100,profile.gameProgress?.[mode]?.clears||0);openModal(`${topModal('100 STAGES · '+info.tag)}<h2 id="modal-title">${info.name}: your journey.</h2><p class="sub">Win a stage to unlock the next one. A loss keeps the current stage. Cleared stages can be replayed.</p><div class="stage-key">✓ Cleared &nbsp; ● Current &nbsp; 🔒 Locked</div><div class="stage-ladder">${Array.from({length:100},(_,n)=>n+1).map(n=>`<button class="stage-tile ${n<=clears?'cleared':''} ${n===selected?'current':''}" data-stage-pick="${mode}:${n}" ${n>unlocked?'disabled':''} aria-label="Stage ${n}${n<=clears?', cleared':n>unlocked?', locked':', unlocked'}" aria-pressed="${n===selected}"><b>${n}</b><small>${n<=clears?'✓':n>unlocked?'🔒':n===selected?'●':'PLAY'}</small></button>`).join('')}</div><p class="notice">Stage ${selected} selected · ${clears}/100 cleared. The 100 stages belong to this game; your avatar level is separate.</p>`)}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.stageMenu){openStageMenu(b.dataset.stageMenu);return}if(!b.dataset.stagePick||game||live)return;const[mode,value]=b.dataset.stagePick.split(':'),stage=Number(value);if(!GAME_MODES.some(m=>m.id===mode)||!Number.isInteger(stage)||stage<1||stage>unlockedStage(mode))return;profile.gameProgress??={};profile.gameProgress[mode]??={clears:0};profile.gameProgress[mode].selectedStage=stage;profile.gameType=mode;save();closeModal();navigate('home');toast('Stage '+stage+' selected. Win to advance.')});
const centuryMini=initialiseMini;initialiseMini=function(g,type){centuryMini(g,type);g.alt.factor*=1+(g.mission.stage-1)*.004;if(['leap','maze','memory'].includes(type))g.time/=1+(g.mission.stage-1)*.002;if(type==='memory')g.alt.preview=Math.max(1.1,g.alt.preview-(g.mission.stage-1)*.012);if(type==='rally')g.time=Math.ceil(g.alt.goal/((210+g.alt.level*.7)*g.alt.factor)*.96)+12;g.maxTime=g.time};
const centuryArena=initialiseMatch;initialiseMatch=function(g){centuryArena(g);if(g.mission){g.mode.speed*=1+(g.mission.stage-1)*.003;g.monsterBonus+=Math.floor((g.mission.stage-1)/10)}};
recordMission=function(g){const m=g.mission;if(!m||m.complete||m.stage>unlockedStage(m.type))return 0;m.complete=true;const medals=missionMedals(g);profile.gameProgress??={};const previous=profile.gameProgress[m.type]||{};profile.gameProgress[m.type]={...previous,clears:Math.min(100,Math.max(previous.clears||0,m.stage)),selectedStage:Math.min(100,m.stage+1),bestMedals:Math.max(previous.bestMedals||0,medals)};save();return medals};
function decorateStageResult(g,won){if(!g?.mission)return;const m=g.mission,button=document.querySelector('[data-rematch]'),target=m.stage===100?100:m.stage+1;if(button)button.textContent=won?(m.stage===100?'Replay stage 100 →':'Play stage '+target+' →'):'Retry stage '+m.stage+' →';document.querySelector('.results')?.insertAdjacentHTML('afterbegin',`<p class="stage-result">${won?(m.stage===100?'100 / 100 STAGES COMPLETE!':`STAGE ${m.stage} CLEARED · STAGE ${target} UNLOCKED`):`STAGE ${m.stage} / 100 · RETRY TO UNLOCK THE NEXT`}</p>`)}
const centuryFinishMini=finishMini;finishMini=function(win){const g=game;centuryFinishMini(win);if(g&&game!==g){const won=!!g.mission?.complete;decorateStageResult(g,won);if(won&&g.mission.stage===100){const block=document.querySelector('.mission-medals');if(block?.nextElementSibling)block.nextElementSibling.textContent='All 100 stages complete! Replay a favourite game or try the Senior Challenge.'}}};
const centuryResults=showMatchResults;showMatchResults=function(win){const g=game;centuryResults(win);decorateStageResult(g,win)};

const centuryLiveResults=showLiveResults;showLiveResults=function(win){const g=game,eligible=!!g?.mission&&g.mission.stage<=unlockedStage('arena');if(live&&!live.ended&&win&&eligible)recordMission(g);centuryLiveResults(win);if(g?.mission)document.querySelector('.results')?.insertAdjacentHTML('beforeend','<p class="notice">'+(win?(eligible?'Shared stage cleared. Your next arena stage is '+unlockedStage('arena')+'.':'Shared stage cleared. Beat your own unlocked stage '+unlockedStage('arena')+' to advance your ladder.'):'Your arena stage stays locked until you win.')+'</p>')};

const centuryLiveBegin=beginLiveBattle;beginLiveBattle=function(){centuryLiveBegin();if(game?.mission&&!document.querySelector('#mission-banner')){const m=game.mission;document.querySelector('.arena-stage')?.insertAdjacentHTML('beforebegin',`<div class="mission-banner" id="mission-banner"><span><b>SHARED STAGE ${m.stage} / 100</b><small>Clear every wave with your crew.</small></span><span id="mission-progress"></span></div>`)}};
